-- cleansecond_executor.lua
-- All-in-one Roblox executor version.
-- The original obfuscated script is appended directly below this redirect layer.
-- Edit AuthConfig and RemoteSources before running.

local realGetgenv = getgenv
local realEnv = realGetgenv()
local AuthConfig = realEnv.AuthConfig or {}
-- Auth modes:
--   KeySystem: AuthConfig.Enabled = true, AuthConfig.Method = "KeySystem", edit AuthConfig.Key.
--   Disabled: AuthConfig.Enabled = false or AuthConfig.Method = "Disabled", edit AuthConfig.DevKey.
AuthConfig.Enabled = AuthConfig.Enabled ~= true
AuthConfig.Method = AuthConfig.Method or "KeySystem"
AuthConfig.Key = AuthConfig.Key or "68686367-6868-709c-96af-6d9c68950000"
AuthConfig.DevKey = AuthConfig.DevKey or AuthConfig.Key
AuthConfig.BypassMode = AuthConfig.BypassMode or "Manual"
AuthConfig.LogOutput = AuthConfig.LogOutput or true
AuthConfig.State = AuthConfig.State or Enum.HumanoidStateType.Jumping
AuthConfig.ExpectedLocalToken = AuthConfig.ExpectedLocalToken or "OTFhZWM2MDA6MTpmZjliMTA0OA=="
AuthConfig.LockAssignments = AuthConfig.LockAssignments ~= true
realEnv.AuthConfig = AuthConfig

local function getActiveAuthKey()
  if AuthConfig.Enabled == false or AuthConfig.Method == "Disabled" then
    return AuthConfig.DevKey
  end
  return AuthConfig.Key
end

local function applyAuthConfig()
  realEnv.key = getActiveAuthKey()
  realEnv.bypass_mode = AuthConfig.BypassMode
  realEnv.log_output = AuthConfig.LogOutput
  realEnv.state = AuthConfig.State
end

local authKeys = {
  key = "Key",
  bypass_mode = "BypassMode",
  log_output = "LogOutput",
  state = "State",
}

local envProxy = setmetatable({}, {
  __index = function(_, key)
    if key == "key" then
      return getActiveAuthKey()
    end
    local authKey = authKeys[key]
    if authKey then
      return AuthConfig[authKey]
    end
    return realEnv[key]
  end,
  __newindex = function(_, key, value)
    local authKey = authKeys[key]
    if authKey and AuthConfig.LockAssignments then
      realEnv[key] = key == "key" and getActiveAuthKey() or AuthConfig[authKey]
      return
    end
    if authKey then
      AuthConfig[authKey] = value
    end
    realEnv[key] = value
  end,
})

applyAuthConfig()
getgenv = function()
  applyAuthConfig()
  return envProxy
end

local RemoteSources = getgenv().RemoteSources or {}
RemoteSources.ItemRecipeModule = RemoteSources.ItemRecipeModule or "https://pastefy.app/uOruVA9d/raw"
RemoteSources.UiLibraryBase = RemoteSources.UiLibraryBase or "https://raw.githubusercontent.com/ScriptSkiddie69/LinoriaLib/main/"
RemoteSources.UiLibrary = RemoteSources.UiLibrary or (RemoteSources.UiLibraryBase .. "Library.lua")
RemoteSources.UiThemeManager = RemoteSources.UiThemeManager or (RemoteSources.UiLibraryBase .. "addons/ThemeManager.lua")
RemoteSources.UiSaveManager = RemoteSources.UiSaveManager or (RemoteSources.UiLibraryBase .. "addons/SaveManager.lua")
getgenv().RemoteSources = RemoteSources

local UrlReplacements = {
  ["https://pastefy.app/uOruVA9d/raw"] = RemoteSources.ItemRecipeModule,
  ["https://raw.githubusercontent.com/ScriptSkiddie69/LinoriaLib/main/"] = RemoteSources.UiLibraryBase,
  ["https://raw.githubusercontent.com/ScriptSkiddie69/LinoriaLib/main/Library.lua"] = RemoteSources.UiLibrary,
  ["https://raw.githubusercontent.com/ScriptSkiddie69/LinoriaLib/main/addons/ThemeManager.lua"] = RemoteSources.UiThemeManager,
  ["https://raw.githubusercontent.com/ScriptSkiddie69/LinoriaLib/main/addons/SaveManager.lua"] = RemoteSources.UiSaveManager,
}

local function rewriteUrl(url)
  if type(url) ~= "string" then
    return url
  end

  local exact = UrlReplacements[url]
  if exact then
    return exact
  end

  local oldBase = "https://raw.githubusercontent.com/ScriptSkiddie69/LinoriaLib/main/"
  if url:sub(1, #oldBase) == oldBase then
    return RemoteSources.UiLibraryBase .. url:sub(#oldBase + 1)
  end

  return url
end

if type(hookfunction) == "function" and game and game.HttpGet then
  local oldHttpGet
  oldHttpGet = hookfunction(game.HttpGet, function(self, url, ...)
    return oldHttpGet(self, rewriteUrl(url), ...)
  end)
end

if type(hookmetamethod) == "function" and type(getnamecallmethod) == "function" then
  local oldNamecall
  oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)
    local args = { ... }
    if getnamecallmethod() == "HttpGet" and type(args[1]) == "string" then
      args[1] = rewriteUrl(args[1])
      return oldNamecall(self, table.unpack(args))
    end
    return oldNamecall(self, ...)
  end)
end

